import csv,sqlite3, collections
with open('csv/frpm.csv') as f: frpm=list(csv.DictReader(f))
conn=sqlite3.connect('db/satscores.db')
cur=conn.cursor()
cur.execute('SELECT cds,sname,dname,cname,AvgScrMath FROM satscores')
sats=cur.fetchall()
conn.close()
frpm_dict={r['CDSCode']:r for r in frpm}
cd=collections.defaultdict(list)
for c,s,d,cn,m in sats:
    if c in frpm_dict and m: cd[c].append(m)
avg={c:sum(v)/len(v) for c,v in cd.items() if v}
for c,v in avg.items():
    if v>400 and 'Riverside' in str(frpm_dict[c]):
        school=frpm_dict[c]['School Name']
        funding=frpm_dict[c]['Charter Funding Type']
        print(f'{school}|{funding}|{v:.1f}')

